const $tabelData = $('#tabelData'),
    $formData = $('#formData'),
    $modalDiv = $('#modalDiv'),
    formCek = CirebonwebForm.FormCek($formData);

$(function () {
    $tabelData.DataTable({
        processing: true,
        serverSide: true,
        ajax: {
            url: `${thisUrl}/tabel`,
            type: 'POST',
            data: function (d) {
                d.filter_konsumen_tipe = $('#filter_konsumen_tipe').val();
                d.filter_produk = $('#filter_produk').val();
            }
        },
        autoWidth: false,
        responsive: true,
        search: { return: true },
        dom: 'Blfrtip',
        buttons: [
            { text: 'Add', action: () => simpan() },
            {
                text: 'Reload',
                action: function (e, dt) {
                    dt.search('').draw();
                    $('#filter_konsumen_tipe, #filter_produk').val('').trigger('change');
                    Swal.fire({
                        icon: 'success',
                        title: 'Informasi',
                        text: 'Selesai reload tabel ke kondisi awal',
                        showConfirmButton: false,
                        timer: 1300
                    }).then(function () { dt.ajax.reload(null, true); });
                }
            },
            { extend: 'excelHtml5', exportOptions: { columns: ':not(.no-export)', orthogonal: 'export' } }
        ],
        columnDefs: [
            { targets: '_all', className: 'dt-head-center' },
            { targets: [0, 1, 3, 4, 5, 6], className: 'dt-body-center' },
            {
                targets: 3,
                className: 'dt-body-right',
                render: function (data, type) {
                    if (type === 'sort' || type === 'export') {
                        return data.replace(/[^\d]/g, '') || 0;
                    }
                    return data;
                }
            },
            { targets: 6, orderable: false }
        ]
    });

    $('#tabelData_filter.dataTables_filter').append($('#filter_konsumen_tipe, #filter_produk'));
    $(document).on('change', '#filter_konsumen_tipe, #filter_produk', function () {
        $tabelData.DataTable().ajax.reload(null, false);
    });

    $(document).on('select2:open', () => document.querySelector('.select2-container--open .select2-search__field')?.focus());

    $('#hargaRp').on('input change', function () {
        const nilai = CirebonwebFormat.unRupiah(this.value);
        $('#harga').val(nilai);
        $(this).val(CirebonwebFormat.Rupiah(nilai));
    });

    $modalDiv.on('shown.bs.modal', function () {
        $('.select2').select2({ tags: true, dropdownParent: $modalDiv });
        formCek.resetInitial();
    }).on('hidden.bs.modal', function () {
        CirebonwebForm.FormReset(this);
        $('.select2.select2-hidden-accessible').select2('destroy');
    });
});

function simpan(id) {
    const $modalTitle = $('.modal-title'),
        $btnSubmit = $('#btnSubmit'),
        postUrl = `${thisUrl}/simpan`;

    if (id > 0) {
        CirebonwebForm.FormFetch(`${thisUrl}/getid`, { id }, 'POST', {}).done(function (response) {
            if (!response.success) return;

            $modalTitle.text('Edit Data');
            $btnSubmit.text('Update');
            $('#id').val(response.data.id);
            $('#konsumen_tipe_id').val(response.data.konsumen_tipe_id).trigger('change');
            $('#produk_id').val(response.data.produk_id).trigger('change');
            $('#harga').val(response.data.harga);
            $('#hargaRp').val(CirebonwebFormat.Rupiah(response.data.harga));
            $modalDiv.modal('show');
        });
    } else {
        $('#id').val('');
        $modalTitle.text('Tambah Data');
        $btnSubmit.text('Simpan');
        $('#konsumen_tipe_id, #produk_id').val('').trigger('change');
        $('#harga').val('0');
        $('#hargaRp').val('0');
        $modalDiv.modal('show');
    }

    $formData.validate($.extend(CirebonwebForm.FormValidasi(), {
        rules: {
            konsumen_tipe_id: { required: true, digits: true },
            produk_id: { required: true, digits: true },
            harga: { required: true, digits: true, min: 0 }
        },
        submitHandler: function () {
            if (!formCek.isChanged()) return false;

            CirebonwebForm.FormFetch(postUrl, $formData.serializeArray(), 'POST', {
                before_call: function () {
                    $btnSubmit.attr('disabled', true).html('<span class="spinner-border spinner-border-sm mr-1"></span> Loading...');
                },
                after_call: function () {
                    $btnSubmit.attr('disabled', false).html('Simpan');
                }
            }).done(function (response) {
                if (!response.success) return;

                $modalDiv.modal('hide');
                Swal.fire({
                    icon: 'success',
                    title: 'Sukses',
                    html: response.messages,
                    showConfirmButton: false,
                    timer: 1300
                }).then(function () { $tabelData.DataTable().ajax.reload(null, false); });
            });

            return false;
        }
    }));
}

function hapus(id) {
    Swal.fire({
        title: 'Konfirmasi',
        html: 'Apakah yakin ingin menghapus data ini? <br> Data akan dihapus secara permanen!',
        icon: 'warning',
        showCancelButton: true,
        confirmButtonColor: '#d33',
        confirmButtonText: 'Ya, hapus!'
    }).then(function (result) {
        if (!result.isConfirmed) return;
        CirebonwebForm.FormFetch(`${thisUrl}/hapus`, { id }, 'POST', {}).done(function (response) {
            if (!response.success) return;
            Swal.fire({ icon: 'success', title: 'Sukses', html: response.messages, showConfirmButton: false, timer: 1300 })
                .then(function () { $tabelData.DataTable().ajax.reload(null, false); });
        });
    });
}
